p<-ggplot()+geom_segment(data=ed,aes(x=x+.5,y=y,xend=xend-.6,yend=yend,linetype=evidence),linewidth=.45,arrow=arrow(length=unit(.10,'inches')))+geom_label(data=nodes,aes(x,y,label=label),size=12/ggplot2::.pt,label.padding=unit(.20,'lines'),fill='white',linewidth=.4)+scale_linetype_manual(values=c('Project association'='solid','General literature'='longdash','Pending connection'='dotted'))+coord_cartesian(xlim=c(-.8,8),ylim=c(-.5,3.5),clip='off')+theme_void(base_family='Arial',base_size=12)+theme(legend.position='bottom');export(p,ed,'F01_frozen_hypothesis',11,4,'Arrows distinguish project association, external mechanism and pending connections; no causal claim for dotted links.')
